Item.method_code:
const self = this;
require([
	'MacPolicy/Scripts/Configurator/MacPolicy'
], function(MacPolicy) {
	const item = self;
	const macPolicy = new MacPolicy(aras, item);
	const result = macPolicy.newVersion();
	if (result.isError()) {
		aras.AlertError(result);
	} else {
		aras.fireEvent('ItemRefresh', {
			itemId: item.getProperty('id'),
			itemLatestVersion: result.node
		});

		const win = aras.uiFindWindowEx(item.getId());
		if (win) {
			aras.uiShowItemEx(result.node);
			win.close();
		} else {
			const message = aras.getResource('../Modules/aras.innovator.MacPolicy/', 'policy.new_version_successs', item.getProperty('name'));
			return ArasModules.Dialog.alert(message, {
				type: 'success'
			});
		}
	}
});
